#include "stdlib/blas/ext/base/ndarray/dwhere.h"
#include "stdlib/ndarray/ctor.h"
#include <stdint.h>

/**
* Takes elements from one of two one-dimensional double-precision floating-point ndarrays depending on a condition.
*
* ## Notes
*
* -   The function expects a one-dimensional boolean condition ndarray, two one-dimensional input ndarrays, and a one-dimensional output ndarray.
* -   A nonzero condition byte selects the first input, matching BooleanArray storage semantics.
*
* @param arrays    list containing ndarrays
*/
void stdlib_blas_ext_dwhere( const struct ndarray *arrays[] ) {
	const struct ndarray *condition = arrays[ 0 ];
	const struct ndarray *x = arrays[ 1 ];
	const struct ndarray *y = arrays[ 2 ];
	const struct ndarray *out = arrays[ 3 ];
	const int64_t N = stdlib_ndarray_dimension( condition, 0 );
	if ( N <= 0 ) {
		return;
	}
	const int64_t strideC = stdlib_ndarray_stride_elements( condition, 0 );
	const int64_t strideX = stdlib_ndarray_stride_elements( x, 0 );
	const int64_t strideY = stdlib_ndarray_stride_elements( y, 0 );
	const int64_t strideOut = stdlib_ndarray_stride_elements( out, 0 );
	int64_t ic = stdlib_ndarray_offset_elements( condition );
	int64_t ix = stdlib_ndarray_offset_elements( x );
	int64_t iy = stdlib_ndarray_offset_elements( y );
	int64_t io = stdlib_ndarray_offset_elements( out );
	const uint8_t *dataC = stdlib_ndarray_data( condition );
	const double *dataX = (const double *)stdlib_ndarray_data( x );
	const double *dataY = (const double *)stdlib_ndarray_data( y );
	double *dataOut = (double *)stdlib_ndarray_data( out );
	for ( int64_t i = 0; i < N; i++ ) {
		if ( dataC[ ic ] != 0 ) {
			dataOut[ io ] = dataX[ ix ];
		} else {
			dataOut[ io ] = dataY[ iy ];
		}
		ic += strideC;
		ix += strideX;
		iy += strideY;
		io += strideOut;
	}
}
